/**
 * colleges.ts — Engineering college directory for the SEO college pages
 * (/colleges → state → college detail).
 *
 * ALL figures (NIRF rank, fees, cutoffs, placements) are INDICATIVE for guidance
 * and should be verified on the official college / counselling website. The UI
 * shows a clear disclaimer. Designed to scale to 100+ colleges — just add entries.
 */

export interface CollegeFull {
  slug: string;                 // url segment, e.g. "iit-bombay"
  name: string;
  shortName?: string;
  city: string;
  state: string;                // must match a StateInfo.name
  type: 'IIT' | 'NIT/IIIT' | 'Government' | 'Private/Deemed';
  established: number;
  nirf: number | null;          // NIRF Engineering rank (indicative, 2024)
  feesTotal: string;            // indicative total B.Tech fees (4 yrs)
  feesPerYear: string;
  hostelPerYear: string;
  accommodation: string;        // hostel / accommodation summary
  exams: string[];              // admission exams
  cutoff: string;               // indicative closing (General) for top branch
  topBranches: string[];
  placementAvg: string;
  placementHighest: string;
  placementRate: string;
  recruiters: string[];
  about: string;
  admissionSteps: string[];
  website: string;
}

export interface StateInfo {
  slug: string;
  name: string;          // must match CollegeFull.state
  emoji: string;
  blurb: string;
  exams: string[];
}

