export function getRankings(c: CollegeFull): RankingEntry[] {
  if (COLLEGE_RANKINGS[c.slug]) return COLLEGE_RANKINGS[c.slug];
  return c.nirf ? [{ source: 'NIRF', rank: `#${c.nirf}` }] : [];
}

/* ─── Helpers ────────────────────────────────────────────────────────────── */
export function getStateInfo(slug: string): StateInfo | undefined {
  return COLLEGE_STATE_INFO.find(s => s.slug === slug);
}
export function getCollegesByState(stateSlug: string): CollegeFull[] {
  const info = getStateInfo(stateSlug);
  if (!info) return [];
  return COLLEGES.filter(c => c.state === info.name)
    .sort((a, b) => (a.nirf ?? 999) - (b.nirf ?? 999));
}
export function getCollegeBySlug(slug: string): CollegeFull | undefined {
  return COLLEGES.find(c => c.slug === slug);
}
export function stateSlugForCollege(c: CollegeFull): string {
  return COLLEGE_STATE_INFO.find(s => s.name === c.state)?.slug ?? 'national';
}
/** All { state, college } slug pairs — used by the sitemap & prerender. */
export function allCollegePaths(): { state: string; college: string }[] {
  return COLLEGES.map(c => ({ state: stateSlugForCollege(c), college: c.slug }));
}

/* ─── Rankings (state-wise & nation-wide) ───────────────────────────────────
   Our indicative ordering: by NIRF where available, then the rest. */
const NATIONAL_ORDER = [...COLLEGES].sort((a, b) => (a.nirf ?? 9999) - (b.nirf ?? 9999));
export function getNationalRank(slug: string): number {
  const i = NATIONAL_ORDER.findIndex(c => c.slug === slug);
  return i < 0 ? 0 : i + 1;
}
export function getStateRank(slug: string): number {
  const c = getCollegeBySlug(slug);
  if (!c) return 0;
  const list = getCollegesByState(stateSlugForCollege(c)); // already sorted by NIRF
  const i = list.findIndex(x => x.slug === slug);
  return i < 0 ? 0 : i + 1;
}
export const TOTAL_COLLEGES = COLLEGES.length;
